//! Golden regression: the DataBar Omnidirectional encoder must reproduce
//! the oracle-extracted 46-run vectors bit-exactly (generated by
//! tools/gen_databar.py, each verified against fresh zint renders).

#[test]
fn databar_golden_vectors() {
    let text = std::fs::read_to_string(concat!(env!("CARGO_MANIFEST_DIR"), "/tests/databar_golden.txt"))
        .expect("golden file");
    let mut n = 0;
    for line in text.lines().filter(|l| !l.trim().is_empty()) {
        let (v, runs) = line.split_once(':').expect("v:runs");
        let v: u64 = v.parse().unwrap();
        let expected: Vec<u32> = runs.split(',').map(|s| s.parse().unwrap()).collect();
        assert_eq!(expected.len(), 46);
        let got = barcode_fixtures::databar_omni_runs(v);
        assert_eq!(got, expected[..], "golden mismatch for v={v}");
        assert_eq!(got.iter().sum::<u32>(), 96);
        n += 1;
    }
    assert!(n >= 60, "expected >=60 golden vectors, got {n}");
}
